def stage_record(rounds):
    if type(rounds) is not int: raise ValueError("STAGE_TYPE")
    for record in RECORDS:
        if record["completed_epochs_candidate"] == rounds: return dict(record)
    raise ValueError("STAGE_UNKNOWN")

def validate_record(record):
    if record != stage_record(record.get("completed_epochs_candidate")):
        raise ValueError("STAGE_RECORD_CHANGED")

